// VideoCarousel.jsx
import React, { useRef, useState, useEffect } from "react";

/*
Usage: <VideoCarousel videoList={[ "/assets/vid1.mp4", "/assets/vid2.mp4" ]} />
Place your mp4s in public/assets or replace with full URLs.
*/
export default function VideoCarousel({ videoList = ["/assets/banner1.mp4", "/assets/banner2.mp4", "/assets/banner3.mp4", "/assets/banner4.mp4"] }) {
  const [index, setIndex] = useState(0);
  const [playing, setPlaying] = useState(false);
  const vRef = useRef(null);

  useEffect(() => {
    // keep play state when switching
    if (playing) vRef.current?.play();
    else vRef.current?.pause();
  }, [index, playing]);

  function togglePlay() {
    setPlaying((p) => {
      const next = !p;
      if (next) vRef.current?.play();
      else vRef.current?.pause();
      return next;
    });
  }

  function prev() {
    setIndex((i) => (i - 1 + videoList.length) % videoList.length);
    setPlaying(false);
  }

  function next() {
    setIndex((i) => (i + 1) % videoList.length);
    setPlaying(false);
  }

  if (!videoList || videoList.length === 0) {
    return <div className="card">No videos configured for banner.</div>;
  }

  return (
    <section className="video-banner card">
      <div className="video-wrapper">
        <video
          ref={vRef}
          src={videoList[index]}
          className="banner-video"
          playsInline
          controls={false}
          onEnded={() => setPlaying(false)}
        />
        <button className="vc-btn prev" onClick={prev} aria-label="Previous">‹</button>
        <button className="vc-btn next" onClick={next} aria-label="Next">›</button>

        <button
          className="play-overlay"
          onClick={togglePlay}
          aria-label={playing ? "Pause" : "Play"}
        >
          {playing ? "❚❚" : "►"}
        </button>

        <div className="video-index">
          {index + 1}/{videoList.length}
        </div>
      </div>
    </section>
  );
}









